function packEntities(entities) {
    let buffer = new ArrayBuffer(4);
    let dataView = new DataView(buffer);
    let offset = 0;
    for (let entity of entities) {
        let id = entity.id;
        let size = entity.size;
        dataView.setUint8(offset, (id << 3) | size);
        offset += 1;
    }
    return buffer;
}

function unpackEntities(buffer) {
    let dataView = new DataView(buffer);
    let entities = [];
    for (let i = 0; i < buffer.byteLength; i += 1) {
        let id = (dataView.getUint8(i) >> 3) & 0x7;
        let size = dataView.getUint8(i) & 0x7;
        entities.push({ id, size });
    }
    return entities;
}
```

