// File: custom-block.php

<?php

namespace YourTheme\Blocks;

class CustomBlock extends \WP_Block_Type {
    public function __construct() {
        parent::__construct(
            'custom/block',
            array(
                'title' => __( 'Custom Block', 'your-text-domain' ),
                'description' => __( 'A custom block with a heading, paragraph, and image.', 'your-text-domain' ),
                'category' => 'common',
                'icon' => 'format-image',
                'keywords' => array( 'custom', 'block' ),
            )
        );
    }

    public function render_callback( $attributes, $content ) {
        $image_url = $attributes['image'];
        $heading = $attributes['heading'];
        $paragraph = $attributes['paragraph'];

        $html = '<div class="custom-block">';
        $html .= '<h2>' . $heading . '</h2>';
        $html .= '<p>' . $paragraph . '</p>';
        $html .= '<img src="' . $image_url . '" alt="' . $heading . '">';
        $html .= '</div>';

        return $html;
    }
}

new CustomBlock();

